def make_floor():
 # Full finite scene wall/shelf/returned supports; no extracted furniture pieces.
 boxes=[((-.25,.10,0),(.25,.14,.48)),((-.25,-.14,.08),(.25,.10,.105))]
 for x in [-.18,.18]:boxes.extend([((x-.012,-.10,.055),(x+.012,.10,.08)),((x-.012,.076,.020),(x+.012,.10,.055))])
 axes=[sorted(set(p[k]for b in boxes for p in b))for k in range(3)];boundary={};faces=[(0,3,2,1),(4,5,6,7),(0,1,5,4),(1,2,6,5),(2,3,7,6),(3,0,4,7)]
 for i in range(len(axes[0])-1):
  for j in range(len(axes[1])-1):
   for k in range(len(axes[2])-1):
    x0,x1=axes[0][i:i+2];y0,y1=axes[1][j:j+2];z0,z1=axes[2][k:k+2];mid=((x0+x1)/2,(y0+y1)/2,(z0+z1)/2)
    if not any(all(lo[t]<mid[t]<hi[t]for t in range(3))for lo,hi in boxes):continue
    v=[(x0,y0,z0),(x1,y0,z0),(x1,y1,z0),(x0,y1,z0),(x0,y0,z1),(x1,y0,z1),(x1,y1,z1),(x0,y1,z1)]
    for f in faces:
     q=tuple(v[t]for t in f);key=tuple(sorted(q))
     if key in boundary:del boundary[key]
     else:boundary[key]=q
 ts=[]
 for q in boundary.values():
  mat=0 if all(p[1]>=.10 for p in q) else 1
  for f in[(0,1,2),(0,2,3)]:ts.append((tuple(q[i]for i in f),mat))
 # One complete closed inset circular mirror area with finite backing and ring lip.
 n=48;cx,cz=-.04,.34;verts=[]
 for radius,y in [(.12,.101),(.12,.080),(.105,.080),(.105,.084)]:
  verts.extend((cx+radius*math.cos(2*math.pi*i/n),y,cz+radius*math.sin(2*math.pi*i/n))for i in range(n))
 back=len(verts);verts.append((cx,.101,cz));front=len(verts);verts.append((cx,.084,cz));mirror=[]
 for i in range(n):
  j=(i+1)%n
  mirror.append(((verts[back],verts[i],verts[j]),2))
  for k in range(3):
   a,b,c,d=k*n+i,k*n+j,(k+1)*n+j,(k+1)*n+i
   mirror.extend([((verts[a],verts[c],verts[b]),2),((verts[a],verts[d],verts[c]),2)])
  mirror.append(((verts[front],verts[3*n+j],verts[3*n+i]),3))
 def volume(tris):return sum((a[0]*(b[1]*c[2]-b[2]*c[1])+a[1]*(b[2]*c[0]-b[0]*c[2])+a[2]*(b[0]*c[1]-b[1]*c[0]))/6 for(a,b,c),m in tris)
 if volume(mirror)<0:mirror=[((a,c,b),m)for(a,b,c),m in mirror]
 ts.extend(mirror)
 mats=[{'name':n,'doubleSided':True,'pbrMetallicRoughness':{'baseColorFactor':color,'metallicFactor':metal,'roughnessFactor':rough}}for n,color,metal,rough in [('SceneWarmWallPatch',[.63,.60,.53,1],0.,.87),('SceneSlateProjectingLedge',[.19,.27,.28,1],0.,.72),('SceneWarmRoundMirrorLip',[.30,.20,.12,1],0.,.65),('SceneInsetMirrorMetallicPBR',[.65,.73,.77,1],1.,.16)]]
 return ts,mats


def main():
 import bpy,sys,time
 from mathutils import Vector
 OUT=Path(__file__).resolve().parent
 inputs={k:zlib.decompress(base64.b64decode(v['compressed']))for k,v in INPUTS.items()}
 for k,raw in inputs.items():assert hashlib.sha256(raw).hexdigest()==INPUTS[k]['sha256']
